function ProductView({ serverData }) {
  const [info, setInfo] = useState(null);

  // Anti-pattern detected
  useEffect(() => {
    if (serverData) {
      setInfo(serverData);
    }
  }, [serverData]);

  return <div>{info?.name}</div>;
}

